mapper.select:
SELECT game_id, equipment_key, name, description, created_at, updated_at FROM public.equipment WHERE game_id = #{gameId}
AND ( strpos(lower(equipment_key), lower(#{keyword})) > 0 OR strpos(lower(name), lower(#{keyword})) > 0 )
ORDER BY name ASC, equipment_key ASC

SELECT game_id, equipment_key, name, description, created_at, updated_at
FROM public.equipment
WHERE game_id = #{gameId} AND equipment_key = #{equipmentKey}

SELECT COUNT(1) FROM public.equipment
WHERE game_id = #{gameId} AND lower(btrim(name)) = lower(btrim(#{name}))

    AND equipment_key <> #{excludeEquipmentKey}

mapper.update:
UPDATE public.equipment
SET name = #{name}, description = #{description}, updated_at = now()
WHERE game_id = #{gameId} AND equipment_key = #{equipmentKey}

mapper.select:
SELECT attribute_values::text
FROM public.equipment_attributes
WHERE game_id = #{gameId} AND equipment_key = #{equipmentKey}

mapper.update:
UPDATE public.equipment_attributes
SET attribute_values = CAST(#{attributeValuesJson} AS jsonb), updated_at = now()
WHERE game_id = #{gameId} AND equipment_key = #{equipmentKey}
